// Shows each display's identifier on that display, and writes the
// identifiers to the console. Set "Display" in GameInputDemo's settings file
// to an identifier, or run it with --display and the identifier, to open it
// on that display.
//
// Each display gets a box in its middle, drawn with GDI. The boxes close when
// one is clicked, or when Esc is pressed while one has focus. With --list, it
// only writes to the console.

// Generated by BindingsGenerator from BindingsGenerator/Filters.txt. Don't edit by hand.
#[path = "Bindings.rs"]
#[allow(
    non_camel_case_types,
    non_snake_case,
    non_upper_case_globals,
    dead_code,
    clippy::all
)]
mod bindings;

// Shared with GameInputDemo, which uses parts of it that this doesn't.
#[path = "Displays.rs"]
#[allow(dead_code)]
mod displays;

use bindings::*;
use displays::Display;
use windows_core::{Error, PCWSTR, Result, w};

// Sizes at 100% scaling, in pixels.
const IDENTIFIER_SIZE: i32 = 120;
const NAME_SIZE: i32 = 30;
const DETAILS_SIZE: i32 = 20;
const HINT_SIZE: i32 = 16;
const PADDING: i32 = 32;
const BORDER: i32 = 4;

// GameInputDemo's colors.
const BACKGROUND: COLORREF = rgb(0x1C1F26);
const ACCENT: COLORREF = rgb(0x4FC1FF);
const TITLE: COLORREF = rgb(0xFFFFFF);
const TEXT: COLORREF = rgb(0xD7DAE0);
const DIM: COLORREF = rgb(0x8B93A1);

// GDI colors are 0x00BBGGRR.
const fn rgb(hex: u32) -> COLORREF {
    COLORREF(((hex & 0xFF) << 16) | (hex & 0xFF00) | ((hex >> 16) & 0xFF))
}

struct Line {
    // Null-terminated UTF-16.
    text: Vec<u16>,
    font: HFONT,
    color: COLORREF,
    // Where the line goes in the box. It's centered across the box's width.
    area: RECT,
}

// What a box draws. Its window keeps a pointer to it.
struct Card {
    lines: Vec<Line>,
    width: i32,
    height: i32,
    border: i32,
    background: HBRUSH,
    accent: HBRUSH,
}

extern "system" fn window_procedure(
    window: HWND,
    message: u32,
    wparam: WPARAM,
    lparam: LPARAM,
) -> LRESULT {
    match message as i32 {
        WM_PAINT => {
            unsafe { paint(window) };
            LRESULT(0)
        }
        WM_LBUTTONDOWN | WM_RBUTTONDOWN => {
            unsafe { PostQuitMessage(0) };
            LRESULT(0)
        }
        WM_KEYDOWN if wparam.0 == VK_ESCAPE as usize => {
            unsafe { PostQuitMessage(0) };
            LRESULT(0)
        }
        _ => unsafe { DefWindowProcW(window, message, wparam, lparam) },
    }
}

unsafe fn paint(window: HWND) {
    unsafe {
        let mut paint = PAINTSTRUCT::default();
        let dc = BeginPaint(window, &mut paint);
        let card = GetWindowLongPtrW(window, GWLP_USERDATA) as *const Card;
        if let Some(card) = card.as_ref() {
            let outer = RECT {
                left: 0,
                top: 0,
                right: card.width,
                bottom: card.height,
            };
            FillRect(dc, &outer, card.accent);
            let inner = RECT {
                left: card.border,
                top: card.border,
                right: card.width - card.border,
                bottom: card.height - card.border,
            };
            FillRect(dc, &inner, card.background);
            SetBkMode(dc, TRANSPARENT);
            for line in &card.lines {
                SelectObject(dc, HGDIOBJ(line.font.0));
                SetTextColor(dc, line.color);
                let mut area = line.area;
                DrawTextW(
                    dc,
                    PCWSTR(line.text.as_ptr()),
                    -1,
                    &mut area,
                    (DT_CENTER | DT_SINGLELINE | DT_NOPREFIX) as u32,
                );
            }
        }
        let _ = EndPaint(window, &paint);
    }
}

fn scale(size: i32, dpi: u32) -> i32 {
    (size as u32 * dpi).div_ceil(USER_DEFAULT_SCREEN_DPI as u32) as i32
}

unsafe fn create_font(size: i32, dpi: u32, bold: bool) -> HFONT {
    unsafe {
        // The identifier is in Consolas, whose 0 has a slash through it.
        let (weight, pitch_and_family, face) = if bold {
            (FW_BOLD, FIXED_PITCH | FF_MODERN, w!("Consolas"))
        } else {
            (FW_NORMAL, FF_SWISS, w!("Segoe UI"))
        };
        CreateFontW(
            -scale(size, dpi),
            0,
            0,
            0,
            weight,
            0,
            0,
            0,
            DEFAULT_CHARSET as u32,
            OUT_DEFAULT_PRECIS as u32,
            CLIP_DEFAULT_PRECIS as u32,
            CLEARTYPE_QUALITY as u32,
            pitch_and_family as u32,
            face,
        )
    }
}

// Lays out the box for one HMONITOR: usually one display, but more if
// monitors clone each other.
unsafe fn layout(displays: &[&Display]) -> Result<Card> {
    unsafe {
        let dpi = displays[0].dpi;
        let identifier_font = create_font(IDENTIFIER_SIZE, dpi, true);
        let name_font = create_font(NAME_SIZE, dpi, false);
        let details_font = create_font(DETAILS_SIZE, dpi, false);
        let hint_font = create_font(HINT_SIZE, dpi, false);

        let mut lines = Vec::new();
        for (index, display) in displays.iter().enumerate() {
            // A gap between the clones.
            if index > 0 {
                lines.push((String::new(), details_font, DIM));
            }
            lines.push((display.identifier.clone(), identifier_font, TITLE));
            lines.push((display.name.clone(), name_font, TEXT));
            let mut details = display.details();
            if display.primary {
                details += ", primary";
            }
            lines.push((details, details_font, DIM));
        }
        lines.push((String::new(), hint_font, DIM));
        lines.push(("Click or press Esc to close".to_string(), hint_font, DIM));

        // Measure each line in a memory DC.
        let dc = CreateCompatibleDC(None);
        if dc.0.is_null() {
            return Err(Error::from_thread());
        }
        let padding = scale(PADDING, dpi);
        let border = scale(BORDER, dpi);
        let mut y = border + padding;
        let mut width = 0;
        let mut card_lines = Vec::new();
        for (text, font, color) in lines {
            // An empty line still measures a line's height.
            let text: Vec<u16> = text.encode_utf16().chain([0]).collect();
            let measure: Vec<u16> = if text.len() == 1 {
                vec![' ' as u16, 0]
            } else {
                text.clone()
            };
            SelectObject(dc, HGDIOBJ(font.0));
            let mut size = RECT::default();
            DrawTextW(
                dc,
                PCWSTR(measure.as_ptr()),
                -1,
                &mut size,
                (DT_CALCRECT | DT_SINGLELINE | DT_NOPREFIX) as u32,
            );
            width = width.max(size.right);
            card_lines.push(Line {
                text,
                font,
                color,
                area: RECT {
                    left: 0,
                    top: y,
                    right: 0,
                    bottom: y + size.bottom,
                },
            });
            y += size.bottom;
        }
        let _ = DeleteDC(dc);

        let width = width + (border + padding) * 2;
        for line in &mut card_lines {
            line.area.right = width;
        }
        Ok(Card {
            lines: card_lines,
            width,
            height: y + padding + border,
            border,
            background: CreateSolidBrush(BACKGROUND),
            accent: CreateSolidBrush(ACCENT),
        })
    }
}

fn print(displays: &[Display], boxes: bool) {
    let count = displays.len();
    println!(
        "{count} {}, from left to right:",
        if count == 1 { "display" } else { "displays" }
    );
    for display in displays {
        let primary = if display.primary {
            ", the primary display"
        } else {
            ""
        };
        let indent = " ".repeat(display.identifier.len() + 4);
        println!();
        println!("  {}  {}{primary}", display.identifier, display.name);
        println!("{indent}{}", display.details());
        println!(
            "{indent}At {}, {} on the desktop",
            display.area.left, display.area.top
        );
        println!("{indent}{}", display.device_path);
    }
    // Where GameInputDemo's Settings.rs keeps its settings.
    let settings = concat!(env!("CARGO_MANIFEST_DIR"), r"\Settings.json");
    println!();
    println!("To open GameInputDemo on a display, set \"Display\" in {settings} to the");
    println!("display's identifier, or run GameInputDemo with --display and the identifier.");
    if boxes {
        println!();
        println!("Click an identifier on screen, or press Esc, to close them.");
    }
}

fn main() -> Result<()> {
    unsafe {
        // Coordinates and sizes in physical pixels, and sharp text at every scale.
        SetProcessDpiAwarenessContext(DPI_AWARENESS_CONTEXT_PER_MONITOR_AWARE_V2).ok()?;
        let mut boxes = true;
        for argument in std::env::args().skip(1) {
            match argument.as_str() {
                "--list" => boxes = false,
                _ => {
                    eprintln!("Unknown command-line argument: {argument}");
                    std::process::exit(2);
                }
            }
        }
        let displays = displays::enumerate()?;
        print(&displays, boxes);
        if displays.is_empty() || !boxes {
            return Ok(());
        }

        let instance = GetModuleHandleW(PCWSTR::null());
        let class_name = w!("DisplayIdentifier");
        let class = WNDCLASSEXW {
            cbSize: size_of::<WNDCLASSEXW>() as u32,
            lpfnWndProc: Some(window_procedure),
            hInstance: instance,
            hCursor: LoadCursorW(None, IDC_ARROW),
            lpszClassName: class_name,
            ..Default::default()
        };
        if RegisterClassExW(&class).0 == 0 {
            return Err(Error::from_thread());
        }

        // Clones share an HMONITOR, and enumerate keeps them next to each other.
        let mut groups: Vec<Vec<&Display>> = Vec::new();
        for display in &displays {
            match groups.last_mut() {
                Some(group) if group[0].monitor == display.monitor => group.push(display),
                _ => groups.push(vec![display]),
            }
        }
        for group in groups {
            let card = layout(&group)?;
            let area = group[0].area;
            let window = CreateWindowExW(
                (WS_EX_TOPMOST | WS_EX_TOOLWINDOW) as u32,
                class_name,
                w!("Display identifier"),
                WS_POPUP,
                area.left + (area.right - area.left - card.width) / 2,
                area.top + (area.bottom - area.top - card.height) / 2,
                card.width,
                card.height,
                None,
                None,
                Some(instance),
                None,
            );
            if window.0.is_null() {
                return Err(Error::from_thread());
            }
            // The card lasts as long as the process, so it's never freed.
            SetWindowLongPtrW(
                window,
                GWLP_USERDATA,
                Box::into_raw(Box::new(card)) as isize,
            );
            let _ = ShowWindow(window, SW_SHOW);
        }

        let mut message = MSG::default();
        while GetMessageW(&mut message, None, 0, 0).as_bool() {
            let _ = TranslateMessage(&message);
            DispatchMessageW(&message);
        }
        Ok(())
    }
}
